let wasRefreshing = false, refreshTimer = null;
function updateRefresh(loading, succeeded = false) {
  refreshButton.disabled = loading;
  refreshButton.setAttribute('aria-busy', String(loading));
  if (loading) {
    clearTimeout(refreshTimer);
    refreshButton.dataset.refreshPhase = 'loading';
    refreshButton.setAttribute('aria-label', '正在刷新数据');
  } else if (wasRefreshing) {
    refreshButton.dataset.refreshPhase = succeeded ? 'success' : 'idle';
    refreshButton.setAttribute('aria-label', succeeded ? '数据更新完成' : '刷新未完成，点击重试');
    if (succeeded) refreshTimer = setTimeout(() => {
      refreshButton.dataset.refreshPhase = 'idle';
      refreshButton.setAttribute('aria-label', '刷新数据');
    }, 1100); // 600ms arrival followed by ~500ms fully-visible confirmation.
  }
  wasRefreshing = loading;
}
window.V2HomeRefresh = Object.freeze({update:updateRefresh});

